package com.smartinventory.repository;
import com.smartinventory.model.AppUser; import org.springframework.data.jpa.repository.JpaRepository; import java.util.Optional;
public interface UserRepository extends JpaRepository<AppUser,Long>{ Optional<AppUser> findByUsernameIgnoreCase(String username); Optional<AppUser> findByEmailIgnoreCase(String email); boolean existsByUsernameIgnoreCase(String username); boolean existsByEmailIgnoreCase(String email); }